// Match: variant-level entry matches if variant was purchased
// Product-level entry matches if any variant of the product was purchased
const isMatch = entry.variant_external_id !== null
  ? variantIdSet.has(entry.variant_external_id)
  : true; // product-level: any purchased variant counts

new_string:
// Match logic:
// - Variant-level: purchased variant must match the entry's specific variant
// - Product-level: purchased variant must belong to the same product the shopper signed up for
//   We check by joining against waitlist_entries product_external_id
let isMatch: boolean;
if (entry.variant_external_id !== null) {
  isMatch = variantIdSet.has(entry.variant_external_id);
} else {
  // Product-level: verify that at least one purchased variant belongs to the entry's product
  // We look up variant→product ownership via a DB query on waitlist_entries
  const productVariantRows = await sql<{ product_external_id: string }[]>`
    SELECT DISTINCT product_external_id::text
    FROM waitlist_entries
    WHERE product_external_id = ${entry.product_external_id}::bigint
    AND variant_external_id = ANY(
      SELECT UNNEST(ARRAY[${sql.array(variantIdStrings)}]::bigint[])
    )
    LIMIT 1
  `;
  isMatch = productVariantRows.length > 0;
}
